// Reverse Shell Generator — command/listener generation logic.
//
// Framework-agnostic pure functions so the page and the unit tests share one
// implementation. The substitution, encoding, OS-filtering and UDP-listener
// behaviour mirrors the upstream revshells.com script (MIT © 2022 Ryan
// Montgomery); see integration/revshells/NOTICE. The payload data lives in
// payloads.generated.ts, regenerated by scripts/revshells.mjs.

import { commands, listeners, shells, specialCommands } from "./payloads.generated.ts";
import type { Command, CommandType, Encoding, Listener, OsFilter, OsTag } from "./types.ts";

export { commands, listeners, shells };
export type { Command, CommandType, Encoding, Listener, OsFilter, OsTag };

/** Command families, in display order, with the tab labels the UI shows. */
export const COMMAND_TYPES: readonly { id: CommandType; label: string }[] = [
    { id: "ReverseShell", label: "Reverse" },
    { id: "BindShell", label: "Bind" },
    { id: "MSFVenom", label: "MSFVenom" },
    { id: "HoaxShell", label: "HoaxShell" },
    { id: "Assembled", label: "Assembled" },
];

/** Encoding options for the encoding selector. */
export const ENCODINGS: readonly { id: Encoding; label: string }[] = [
    { id: "None", label: "None" },
    { id: "encodeURL", label: "URL Encode" },
    { id: "encodeURLDouble", label: "Double URL Encode" },
    { id: "Base64", label: "Base64" },
];

/** OS filter options. */
export const OS_FILTERS: readonly { id: OsFilter; label: string }[] = [
    { id: "all", label: "All" },
    { id: "linux", label: "Linux" },
    { id: "windows", label: "Windows" },
    { id: "mac", label: "Mac" },
];

const COMMAND_TYPE_SET = new Set<string>(COMMAND_TYPES.map((t) => t.id));
const OS_TAGS: readonly OsTag[] = ["linux", "windows", "mac"];
const DEFAULT_PAYLOAD = "windows/x64/meterpreter/reverse_tcp";

/** The command family a payload belongs to (the CommandType tag in its meta). */
export function getCommandType(command: Command): CommandType {
    const tag = command.meta.find((m) => COMMAND_TYPE_SET.has(m));
    return (tag as CommandType) ?? "ReverseShell";
}

/** The OS tags a command is marked for. */
export function getOsTags(command: Command): OsTag[] {
    return command.meta.filter((m): m is OsTag => (OS_TAGS as readonly string[]).includes(m));
}

/** Commands of a given family, optionally filtered to a single OS. */
export function filterCommands(type: CommandType, os: OsFilter = "all"): Command[] {
    return commands.filter((command) => {
        if (getCommandType(command) !== type) return false;
        if (os === "all") return true;
        const tags = getOsTags(command);
        // Commands with no OS tag (e.g. language runtimes) show under every OS.
        return tags.length === 0 || tags.includes(os);
    });
}

// --- encoding helpers ---------------------------------------------------------

/** encodeURIComponent, also escaping ! ' ( ) * — matches the upstream encoder. */
export function fixedEncodeURIComponent(str: string): string {
    return encodeURIComponent(str).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
}

/** Base64 of a byte array, via btoa over a latin1 string (browser + Node). */
function bytesToBase64(bytes: Uint8Array): string {
    let binary = "";
    for (const byte of bytes) binary += String.fromCharCode(byte);
    return btoa(binary);
}

/** Base64 of UTF-8 bytes. Robust for non-ASCII payloads (upstream used raw btoa). */
function base64Utf8(text: string): string {
    return bytesToBase64(new TextEncoder().encode(text));
}

/** Base64 of UTF-16LE bytes — what PowerShell -EncodedCommand expects. */
function base64Utf16le(text: string): string {
    const bytes = new Uint8Array(text.length * 2);
    for (let i = 0; i < text.length; i++) {
        const code = text.charCodeAt(i);
        bytes[i * 2] = code & 0xff;
        bytes[i * 2 + 1] = code >> 8;
    }
    return bytesToBase64(bytes);
}

// --- variable substitution ----------------------------------------------------

/** IP/port as \x.. byte strings, for the Assembled (shellcode) payloads. */
function toBytes(ip: string, port: number): { ip: string; port: string } {
    let ipOut: string;
    if (ip.split(".").length === 4) {
        ipOut = ip
            .split(".")
            .map((x) => {
                const octet = parseInt(x, 10);
                if (!isNaN(octet) && octet >= 0 && octet <= 0xff) return `\\x${octet.toString(16).padStart(2, "0")}`;
                return "\\x..";
            })
            .join("");
    } else {
        ipOut = "\\x..\\x..\\x..\\x..";
    }

    let portOut: string;
    if (!isNaN(port)) {
        const hex = port.toString(16).padStart(4, "0");
        portOut = (hex.match(/.{2}/g) ?? []).map((b) => `\\x${b}`).join("");
    } else {
        portOut = "\\x..\\x..";
    }

    return { ip: ipOut, port: portOut };
}

type Vars = { ip: string; port: number; shell: string };
type Encoder = (text: string) => string;

/** Replace {ip}/{port}/{shell}, encoding both the placeholder and the value. */
function insertParameters(command: string, encoder: Encoder, vars: Vars, assembled: boolean): string {
    let { ip, port } = { ip: vars.ip, port: String(vars.port) };
    if (assembled) {
        const bytes = toBytes(vars.ip, vars.port);
        ip = bytes.ip;
        port = bytes.port;
    }
    return command
        .replaceAll(encoder("{ip}"), encoder(ip))
        .replaceAll(encoder("{port}"), encoder(port))
        .replaceAll(encoder("{shell}"), encoder(vars.shell));
}

const SPECIAL_POWERSHELL: Record<string, string> = {
    "PowerShell #3 (Base64)": "PowerShell payload",
    "PowerShell #5 (stderr support) (Base64)": "PowerShell +stderr payload",
};

export type BuildOptions = {
    ip: string;
    port: number;
    shell: string;
    encoding?: Encoding;
};

/** The final, copy-ready command string for a payload. */
export function buildCommand(command: Command, options: BuildOptions): string {
    const { ip, port, shell, encoding = "None" } = options;
    const vars: Vars = { ip, port, shell };
    const assembled = getCommandType(command) === "Assembled";

    // PowerShell #3/#5 are assembled into a base64 -EncodedCommand before the
    // outer encoding runs, exactly as upstream special-cases them.
    let base: string;
    const specialKey = SPECIAL_POWERSHELL[command.name];
    if (specialKey) {
        const identity: Encoder = (t) => t;
        const payload = insertParameters(specialCommands[specialKey], identity, vars, false);
        base = `powershell -e ${base64Utf16le(payload)}`;
    } else {
        base = command.command;
    }

    const identity: Encoder = (t) => t;
    switch (encoding) {
        case "Base64":
            return base64Utf8(insertParameters(base, identity, vars, assembled));
        case "encodeURL": {
            const enc: Encoder = (t) => fixedEncodeURIComponent(t);
            return insertParameters(enc(base), enc, vars, assembled);
        }
        case "encodeURLDouble": {
            const enc: Encoder = (t) => fixedEncodeURIComponent(fixedEncodeURIComponent(t));
            return insertParameters(enc(base), enc, vars, assembled);
        }
        default:
            return insertParameters(base, identity, vars, assembled);
    }
}

// --- listeners ----------------------------------------------------------------

/** The MSF payload for a selected command: its -p value, or the default. */
export function getPayload(selected: Command | undefined): string {
    if (selected && getCommandType(selected) === "MSFVenom") {
        const match = /\s+-p\s+([a-zA-Z0-9/_]+)/.exec(selected.command);
        if (match?.[1]) return match[1];
    }
    return DEFAULT_PAYLOAD;
}

/** HoaxShell command name -> listener type; "cmd-curl" by default. */
const HOAXSHELL_TYPES: Record<string, string> = {
    "Windows CMD cURL": "cmd-curl",
    "PowerShell IEX": "ps-iex",
    "PowerShell IEX Constr Lang Mode": "ps-iex-cm",
    "PowerShell Outfile": "ps-outfile",
    "PowerShell Outfile Constr Lang Mode": "ps-outfile-cm",
    "Windows CMD cURL https": "cmd-curl -c /your/cert.pem -k /your/key.pem",
    "PowerShell IEX https": "ps-iex -c /your/cert.pem -k /your/key.pem",
    "PowerShell IEX Constr Lang Mode https": "ps-iex-cm -c /your/cert.pem -k /your/key.pem",
    "PowerShell Outfile https": "ps-outfile -c /your/cert.pem -k /your/key.pem",
    "PowerShell Outfile Constr Lang Mode https": "ps-outfile-cm -c /your/cert.pem -k /your/key.pem",
};

function getListenerType(selected: Command | undefined): string {
    if (selected && getCommandType(selected) === "HoaxShell") return HOAXSHELL_TYPES[selected.name] ?? "cmd-curl";
    return "cmd-curl";
}

const UDP_PAYLOADS = new Set(["Bash udp", "ncat udp"]);

export type ListenerResult = {
    /** The listener command, or "" when the listener can't support the selection. */
    command: string;
    /** A caveat to show instead of / alongside the command (UDP limitations). */
    warning?: string;
    /** True when the port is privileged (<1024) and the command needs sudo. */
    needsSudo: boolean;
};

export type ListenerOptions = {
    ip: string;
    port: number;
    /** The currently selected reverse-shell command, for payload/type/UDP hints. */
    selected?: Command;
};

/** Build a listener command, adapting it for UDP payloads the way upstream does. */
export function buildListener(listener: Listener, options: ListenerOptions): ListenerResult {
    const { ip, port, selected } = options;
    let command = listener.command;
    let warning: string | undefined;

    const isUDP = selected ? UDP_PAYLOADS.has(selected.name) : false;
    if (isUDP) {
        let udpSupported = true;
        if (/^nc\s/.test(command) && !/\s-u(\s|$)/.test(command)) {
            command = command.replace(/^(nc)(\s+)/, "$1 -u$2");
        } else if (/^ncat(\s|\.|\s--ssl)/.test(command) && !/\s-u(\s|$)/.test(command)) {
            if (/--ssl/.test(command)) {
                udpSupported = false;
                warning = "SSL/TLS (--ssl) is not supported over UDP with ncat.";
            } else {
                command = command.replace(/^(ncat(\.exe)?( --ssl)?)(\s+)/, "$1 -u$4");
            }
        } else if (/^busybox nc\s/.test(command) && !/\s-u(\s|$)/.test(command)) {
            command = command.replace(/^(busybox nc)(\s+)/, "$1 -u$2");
        } else if (/^rlwrap -cAr nc\s/.test(command) && !/\s-u(\s|$)/.test(command)) {
            command = command.replace(/^(rlwrap -cAr nc)(\s+)/, "$1 -u$2");
        } else if (/^nc freebsd\s/.test(command)) {
            command = command.replace(/^nc freebsd\s+-lvn(\s+)\{port\}/, "nc freebsd -lun {port}");
        } else if (/^rcat listen/.test(command) && !/\s-u(\s|$)/.test(command)) {
            command = command.replace(/^(rcat listen)(\s+)/, "$1 -u$2");
        } else if (/^python3 -m pwncat( -m windows)?(\s+)/.test(command) && !/\s-u(\s|$)/.test(command)) {
            command = command.replace(/^(python3 -m pwncat( -m windows)?)(\s+)/, "$1 -u$3");
        } else if (/^socat\b/.test(command)) {
            command = command.replace(/TCP-LISTEN:/g, "UDP-LISTEN:").replace(/TCP:/g, "UDP:");
        } else if (/^openssl\b/.test(command)) {
            command = "openssl s_server -dtls -accept {port} -cert server-cert.pem -key server-key.pem";
        } else if (/^msfconsole\b/.test(command)) {
            udpSupported = false;
            warning = "UDP payloads are not currently supported in msfconsole by this generator.";
        } else if (/^powercat\b/.test(command)) {
            udpSupported = false;
            warning = "powercat does not support UDP listeners.";
        } else if (/hoaxshell-listener\.py/.test(command)) {
            udpSupported = false;
            warning = "hoaxshell does not support UDP listeners.";
        } else if (/stty raw -echo; \(stty size; cat\) \| nc /.test(command)) {
            udpSupported = false;
            warning = "UDP is not natively supported for Windows ConPty listeners.";
        }
        if (!udpSupported && !warning) {
            warning = "This listener may not support UDP. Please verify manually.";
        }
        if (!udpSupported) return { command: "", warning, needsSudo: false };
    }

    command = command
        .replaceAll("{port}", String(port))
        .replaceAll("{ip}", ip)
        .replaceAll("{payload}", getPayload(selected))
        .replaceAll("{type}", getListenerType(selected));

    return { command, warning, needsSudo: port < 1024 };
}
